require_once __DIR__.'/../includes/bootstrap.php';require_role('recruiter');$user=current_user();$flashes=render_flashes();$currentPage='shortlists';$pageTitle='Shortlists';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$candidateId=(int)($_GET['candidate_id']??$_POST['candidate_id']??0);if($uid<=0){http_response_code(403);exit('Invalid Recruiter account.');}
if($_SERVER['REQUEST_METHOD']==='POST'){rc_verify_csrf();$action=(string)($_POST['action']??'');if($action==='create'){$name=trim((string)($_POST['name']??''));$client=trim((string)($_POST['client_name']??''));$criteria=(string)($_POST['criteria']??'{}');$tax=trim((string)($_POST['taxonomy_version']??''))?:rc_taxonomy_version($conn);if($name===''){rc_flash('danger','Shortlist name is required.');header('Location: '.url('recruiter/shortlists.php'));exit;}$s=$conn->prepare("INSERT INTO recruiter_shortlists(recruiter_id,name,client_name,search_criteria_json,taxonomy_version) VALUES(?,?,?,?,?)");$s->bind_param('issss',$uid,$name,$client,$criteria,$tax);$s->execute();$sid=$s->insert_id;$s->close();if($candidateId>0){$s=$conn->prepare("INSERT IGNORE INTO recruiter_shortlist_candidates(shortlist_id,candidate_id,added_by) SELECT ?,cp.user_id,? FROM candidate_profiles cp JOIN candidate_consents cc ON cc.candidate_id=cp.user_id AND cc.consent_type='recruiter_discovery' AND cc.status='consented' AND (cc.expires_at IS NULL OR cc.expires_at>NOW()) WHERE cp.user_id=?");$s->bind_param('iii',$sid,$uid,$candidateId);$s->execute();$s->close();}rc_activity($conn,$uid,'shortlist_created','Created a shortlist with stored search criteria and taxonomy version.','shortlist',$sid);header('Location: '.url('recruiter/shortlist_view.php?id='.$sid));exit;} if($action==='add'){$sid=(int)($_POST['shortlist_id']??0);$s=$conn->prepare("SELECT id FROM recruiter_shortlists WHERE id=? AND recruiter_id=?");$s->bind_param('ii',$sid,$uid);$s->execute();$ok=$s->get_result()->fetch_assoc();$s->close();if(!$ok){http_response_code(403);exit('Access denied.');}$s=$conn->prepare("INSERT IGNORE INTO recruiter_shortlist_candidates(shortlist_id,candidate_id,added_by) SELECT ?,cp.user_id,? FROM candidate_profiles cp JOIN candidate_consents cc ON cc.candidate_id=cp.user_id AND cc.consent_type='recruiter_discovery' AND cc.status='consented' AND (cc.expires_at IS NULL OR cc.expires_at>NOW()) WHERE cp.user_id=?");$s->bind_param('iii',$sid,$uid,$candidateId);$s->execute();$s->close();header('Location: '.url('recruiter/shortlist_view.php?id='.$sid));exit;}}
$rows=[];if(rc_has_table($conn,'recruiter_shortlists')){$s=$conn->prepare("SELECT rs.*,COUNT(rsc.id) candidate_count FROM recruiter_shortlists rs LEFT JOIN recruiter_shortlist_candidates rsc ON rsc.shortlist_id=rs.id WHERE rs.recruiter_id=? GROUP BY rs.id ORDER BY rs.updated_at DESC");$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}$criteria=['skill'=>$_GET['skill']??'','province'=>$_GET['province']??'','verification'=>$_GET['verification']??'','max_age_days'=>(int)($_GET['max_age_days']??0),'scarce_only'=>(int)($_GET['scarce_only']??0)];$tax=trim((string)($_GET['taxonomy_version']??''))?:rc_taxonomy_version($conn);require __DIR__.'/_layout_start.php';?>
<div class="rc-page-header"><span class="rc-eyebrow">Client Response</span><h2>Shortlists</h2><p>Preserve search criteria and taxonomy version with each client shortlist.</p></div>
<?php if($candidateId>0&&$rows):?><div class="rc-card rc-space"><div class="rc-card__header"><h3>Add Candidate to Existing Shortlist</h3></div><div class="rc-choice"><?php foreach($rows as $x):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(rc_csrf())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="candidate_id" value="<?=$candidateId?>"><input type="hidden" name="shortlist_id" value="<?=$x['id']?>"><div><strong><?=e($x['name'])?></strong><span><?=number_format((int)$x['candidate_count'])?> candidates · <?=e($x['taxonomy_version'])?></span></div><button class="rc-btn rc-btn--secondary rc-btn--small">Add</button></form><?php endforeach;?></div></div><?php endif;?>
<div class="rc-card rc-space"><div class="rc-card__header"><h3>Create New Shortlist</h3></div><form method="post" class="rc-card__body rc-form-3"><input type="hidden" name="csrf_token" value="<?=e(rc_csrf())?>"><input type="hidden" name="action" value="create"><input type="hidden" name="candidate_id" value="<?=$candidateId?>"><input type="hidden" name="criteria" value="<?=e(json_encode($criteria,JSON_UNESCAPED_SLASHES))?>"><input type="hidden" name="taxonomy_version" value="<?=e($tax)?>"><div class="rc-field"><label>Shortlist Name</label><input name="name" required placeholder="Java Cloud - Gauteng"></div><div class="rc-field"><label>Client</label><input name="client_name" placeholder="Client name"></div><div class="rc-field"><label>Taxonomy</label><input value="<?=e($tax)?>" readonly></div><button class="rc-btn rc-btn--primary"><i class="fas fa-plus"></i> Create Shortlist</button></form></div>
<div class="rc-shortlist-grid"><?php foreach($rows as $x):?><article class="rc-shortlist-card"><i class="fas fa-list-check"></i><h3><?=e($x['name'])?></h3><p><?=e((string)($x['client_name']?:'No client specified'))?></p><div><span><?=number_format((int)$x['candidate_count'])?> candidates</span><span>Taxonomy <?=e($x['taxonomy_version'])?></span></div><a class="rc-btn rc-btn--secondary" href="<?=url('recruiter/shortlist_view.php?id='.$x['id'])?>">Open Shortlist</a></article><?php endforeach;?></div>
<?php require __DIR__.'/_layout_end.php';?>